px(x+4,y+15,9,1,0x4A7659) -- tiny shadow
if pose=="run1" then
body_y=y+7
leg1_x=x+3
leg2_x=x+11
elseif pose=="run2" then
body_y=y+6
leg_y=y+14
leg1_x=x+5
leg2_x=x+9
elseif pose=="jump" then
body_y=y+5
leg_y=y+11
leg1_x=x+5
leg2_x=x+9
tail_x=(dir>0) and x or (x+14)
elseif pose=="fall" then
