px(leg2_x,leg_y,2,3,0x111824)
px(x+6,y+7,4,3,0xEAEFF5)
if not blink then
if dir>0 then
px(x+7,y+4,1,2,0xF5F5F5)
px(x+11,y+4,1,2,0xF5F5F5)
else
px(x+4,y+4,1,2,0xF5F5F5)
