p.dir=1
p.pose="idle"
p.anim_t=0
p.step_t=0
p.step_emit=0
p.standing_mover=nil
p.checkpoint_id=0
G.coin_alive={}
for n=1,#G.st.coins do G.coin_alive[n]=true end
G.key_alive={}
