e.kind=d[1]
e.x=d[2]
e.y=d[3]
e.base_y=d[3]
e.origin=d[2]
e.range=d[4]
e.vx=(d[1]=="slug") and 26 or 0
e.vy=0
e.t=n*0.7
e.dir=1
end
for n=1,#G.boxes do G.boxes[n].active=false end
